/**
 * EIP-712 signing core for SoDEX, ported from the reference Go SDK
 * (sodex-tech/sodex-go-sdk-public: common/types/eip712.go, common/signer/evm_signer.go)
 * via Opentrade/server/src/signing/eip712.ts.
 *
 * Verified byte-for-byte against the Go implementation - see test/vectors.test.ts
 * and test/vectors-sdk.test.ts, whose fixtures are generated by
 * tools/genvectors/main.go.
 *
 * Browser-safe: only @noble/*, Uint8Array and TextEncoder. No Buffer, no node:*.
 */
import { keccak_256 } from '@noble/hashes/sha3';
import { utf8ToBytes } from '@noble/hashes/utils';
import { secp256k1 } from '@noble/curves/secp256k1';

import { DomainName } from './network.ts';

export { DomainName };

export type Hex = `0x${string}`;

/** enums.SignatureType - the leading byte of the 66-byte wire signature. */
export const SignatureType = {
  /** Exchange actions (orders, cancels, transfers, revokeAPIKey) - engine-specific domain. */
  EIP712: 1,
  /** API-key lifecycle and builder approval - the "universal" domain. */
  EIP712Universal: 2,
} as const;
export type SignatureTypeValue = (typeof SignatureType)[keyof typeof SignatureType];

export const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000';

// ---------------------------------------------------------------------------
// Bytes helpers
// ---------------------------------------------------------------------------

export const bytesToHex = (b: Uint8Array): Hex =>
  ('0x' + Array.from(b, (x) => x.toString(16).padStart(2, '0')).join('')) as Hex;

const HEX_BODY_RE = /^[0-9a-fA-F]*$/;

/**
 * Hex string (0x-prefix optional) to bytes.
 *
 * Stricter than Opentrade's: a non-hex digit used to parse as NaN and land in
 * the array as 0, silently signing over the wrong bytes. It now throws.
 */
export function hexToBytes(h: string): Uint8Array {
  const s = h.startsWith('0x') || h.startsWith('0X') ? h.slice(2) : h;
  if (s.length % 2 !== 0) throw new Error(`odd-length hex: ${h}`);
  if (!HEX_BODY_RE.test(s)) throw new Error('not a hex string');
  const out = new Uint8Array(s.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = Number.parseInt(s.slice(i * 2, i * 2 + 2), 16);
  return out;
}

export const concat = (...parts: Uint8Array[]): Uint8Array => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) {
    out.set(p, o);
    o += p.length;
  }
  return out;
};

/**
 * UTF-8 encode. Via noble's `utf8ToBytes` (TextEncoder underneath) so this
 * package needs neither DOM nor Node typings. Lone surrogates become U+FFFD,
 * exactly what the browser's fetch() does to the body - so the bytes hashed
 * are the bytes sent.
 */
export const utf8 = (s: string): Uint8Array => utf8ToBytes(s);

const MAX_UINT256 = (1n << 256n) - 1n;

/** Big-endian left-padded 32-byte word from a bigint/number/decimal string. */
export function word(n: bigint | number | string): Uint8Array {
  let v = BigInt(n);
  if (v < 0n) throw new Error('negative word');
  if (v > MAX_UINT256) throw new Error('word overflows uint256');
  const out = new Uint8Array(32);
  for (let i = 31; i >= 0 && v > 0n; i--) {
    out[i] = Number(v & 0xffn);
    v >>= 8n;
  }
  return out;
}

/** 32-byte left-padded address. */
const addressWord = (addr: string): Uint8Array => {
  const b = hexToBytes(addr);
  if (b.length !== 20) throw new Error(`expected a 20-byte address, got ${b.length} bytes`);
  const out = new Uint8Array(32);
  out.set(b, 12);
  return out;
};

const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;
export const isAddress = (a: unknown): a is Hex => typeof a === 'string' && ADDRESS_RE.test(a);

/** EIP-55 mixed-case checksum form of an address (display and comparison aid). */
export function toChecksumAddress(address: string): Hex {
  if (!isAddress(address)) throw new Error('not a 20-byte 0x address');
  const lower = address.slice(2).toLowerCase();
  const hash = bytesToHex(keccak_256(utf8(lower))).slice(2);
  let out = '0x';
  for (let i = 0; i < 40; i++) {
    const c = lower[i]!;
    out += Number.parseInt(hash[i]!, 16) >= 8 ? c.toUpperCase() : c;
  }
  return out as Hex;
}

/** Case-insensitive address equality. */
export const sameAddress = (a: string, b: string): boolean =>
  isAddress(a) && isAddress(b) && a.toLowerCase() === b.toLowerCase();

/** keccak256 helper re-exported so callers need not depend on noble directly. */
export const keccak256 = (b: Uint8Array): Uint8Array => keccak_256(b);

// ---------------------------------------------------------------------------
// Domain
// ---------------------------------------------------------------------------

const DOMAIN_TYPEHASH = keccak_256(
  utf8('EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)'),
);

export interface Domain {
  name: string;
  version: string;
  chainId: number;
  verifyingContract: string;
}

export const makeDomain = (name: string, chainId: number): Domain => ({
  name,
  version: '1',
  chainId,
  verifyingContract: ZERO_ADDRESS,
});

export const domainSeparator = (d: Domain): Uint8Array =>
  keccak_256(
    concat(
      DOMAIN_TYPEHASH,
      keccak_256(utf8(d.name)),
      keccak_256(utf8(d.version)),
      word(d.chainId),
      addressWord(d.verifyingContract),
    ),
  );

/** keccak256(0x1901 || domainSeparator || structHash) */
export const eip712Digest = (d: Domain, structHash: Uint8Array): Uint8Array =>
  keccak_256(concat(new Uint8Array([0x19, 0x01]), domainSeparator(d), structHash));

// ---------------------------------------------------------------------------
// ExchangeAction - the envelope for every trading action
// ---------------------------------------------------------------------------

export const EXCHANGE_ACTION_TYPE = 'ExchangeAction(bytes32 payloadHash,uint64 nonce)';
const EXCHANGE_ACTION_TYPEHASH = keccak_256(utf8(EXCHANGE_ACTION_TYPE));

export const exchangeActionStructHash = (payloadHash: Uint8Array, nonce: bigint): Uint8Array =>
  keccak_256(concat(EXCHANGE_ACTION_TYPEHASH, payloadHash, word(nonce)));

/**
 * payloadHash = keccak256(goJSON({ "type": <action>, "params": <body> }))
 *
 * The server recomputes this by re-marshalling with Go's encoding/json, so the
 * serialisation must match Go byte-for-byte: struct field order, omitted
 * `omitempty` fields, decimals as strings, HTML escaping on.
 */
export const actionPayloadHash = (type: string, params: unknown): Uint8Array =>
  keccak_256(utf8(goJSONStringify({ type, params })));

/**
 * The exact signing payload for an action whose HTTP body is `bodyJSON`.
 *
 * `goJSONStringify({type, params})` and this produce identical bytes; this form
 * exists so a caller that already serialised the body ONCE can hash exactly the
 * bytes it will send (request.ts relies on it).
 */
export const payloadJSONFromBody = (type: string, bodyJSON: string): string =>
  '{"type":' + goJSONStringify(type) + ',"params":' + bodyJSON + '}';

/** Full EIP-712 digest of an exchange action (what the API key - or master wallet - signs). */
export function exchangeActionDigest(
  domainName: string,
  chainId: number,
  actionType: string,
  params: unknown,
  nonce: bigint,
): Uint8Array {
  return eip712Digest(
    makeDomain(domainName, chainId),
    exchangeActionStructHash(actionPayloadHash(actionType, params), nonce),
  );
}

// ---------------------------------------------------------------------------
// Go-compatible JSON
// ---------------------------------------------------------------------------

/**
 * Serialise exactly as Go's `encoding/json` would.
 *
 * The only meaningful divergence from JSON.stringify is that Go escapes
 * `<`, `>` and `&` by default (SetEscapeHTML(true)). Our payloads rarely
 * contain them, but a mismatch would surface as an opaque 401, so it is
 * handled. Key order is preserved from insertion order - callers MUST build
 * objects in Go struct field order.
 *
 * Valuescan addition: Go (>= 1.22) also writes `\b` and `\f` as short escapes
 * and always escapes U+2028 / U+2029. Pinned against Go 1.26's encoding/json by
 * the `goJSONStrings` fixture in test/vectors-sdk.json. The gateway's Go
 * version is unknown, but every string the gateway accepts in a signed payload
 * (clOrdID, key names) is limited to [0-9A-Za-z_-], so this never bites there.
 */
export function goJSONStringify(value: unknown): string {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'string') return goQuote(value);
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error('non-finite number in payload');
    if (!Number.isInteger(value)) {
      throw new Error(`non-integer number in payload: ${value} (decimals must be strings)`);
    }
    // Above 2^53 a JS number no longer round-trips; uint64 ids must be bigint.
    if (!Number.isSafeInteger(value)) {
      throw new Error(`unsafe integer in payload: ${value} (pass a bigint)`);
    }
    return String(value);
  }
  if (typeof value === 'bigint') return value.toString();
  if (Array.isArray(value)) return '[' + value.map(goJSONStringify).join(',') + ']';
  if (typeof value === 'object') {
    const parts: string[] = [];
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (v === undefined) continue; // mirrors Go `omitempty` on a nil pointer
      parts.push(goQuote(k) + ':' + goJSONStringify(v));
    }
    return '{' + parts.join(',') + '}';
  }
  throw new Error(`cannot serialise ${typeof value}`);
}

function goQuote(s: string): string {
  let out = '"';
  for (const ch of s) {
    const c = ch.codePointAt(0)!;
    switch (ch) {
      case '"':
        out += '\\"';
        continue;
      case '\\':
        out += '\\\\';
        continue;
      case '\n':
        out += '\\n';
        continue;
      case '\r':
        out += '\\r';
        continue;
      case '\t':
        out += '\\t';
        continue;
      case '\b':
        out += '\\b';
        continue;
      case '\f':
        out += '\\f';
        continue;
      // Go's encoding/json escapes these by default to keep JSON safe to embed in HTML.
      case '<':
        out += '\\u003c';
        continue;
      case '>':
        out += '\\u003e';
        continue;
      case '&':
        out += '\\u0026';
        continue;
      // ...and these two always, for JSONP safety.
      case ' ':
        out += '\\u2028';
        continue;
      case ' ':
        out += '\\u2029';
        continue;
    }
    out += c < 0x20 ? '\\u' + c.toString(16).padStart(4, '0') : ch;
  }
  return out + '"';
}

// ---------------------------------------------------------------------------
// Generic EIP-712 hashing for the FLAT typed-data objects handed to wallets
// ---------------------------------------------------------------------------

export interface TypedDataField {
  name: string;
  type: string;
}

/**
 * An `eth_signTypedData_v4` payload. Integer message fields are carried as
 * decimal STRINGS so uint64 values above 2^53 survive JSON; wallets accept that.
 */
/** A typed-data value: atomic, or a nested struct (the permit's `cmd`). */
export type TypedDataValue = string | number | boolean | bigint | { readonly [k: string]: TypedDataValue };

export interface TypedData<P extends string = string> {
  domain: { name: string; version: string; chainId: number; verifyingContract: string };
  types: Record<string, readonly TypedDataField[]>;
  primaryType: P;
  message: Record<string, TypedDataValue>;
}

export const EIP712_DOMAIN_FIELDS: readonly TypedDataField[] = [
  { name: 'name', type: 'string' },
  { name: 'version', type: 'string' },
  { name: 'chainId', type: 'uint256' },
  { name: 'verifyingContract', type: 'address' },
];

/** `Name(type1 name1,type2 name2)` - flat structs only (no referenced struct types). */
export const encodeFlatType = (primaryType: string, fields: readonly TypedDataField[]): string =>
  `${primaryType}(${fields.map((f) => `${f.type} ${f.name}`).join(',')})`;

function encodeField(type: string, value: unknown, where: string): Uint8Array {
  if (type === 'string') {
    if (typeof value !== 'string') throw new TypeError(`${where}: expected string`);
    return keccak_256(utf8(value));
  }
  if (type === 'bytes') {
    if (typeof value !== 'string') throw new TypeError(`${where}: expected hex bytes`);
    return keccak_256(hexToBytes(value));
  }
  if (type === 'bytes32') {
    if (typeof value !== 'string') throw new TypeError(`${where}: expected bytes32 hex`);
    const b = hexToBytes(value);
    if (b.length !== 32) throw new RangeError(`${where}: bytes32 must be 32 bytes`);
    return b;
  }
  if (type === 'address') {
    if (typeof value !== 'string') throw new TypeError(`${where}: expected address`);
    return addressWord(value);
  }
  if (type === 'bool') return word(value ? 1 : 0);
  const m = /^uint(\d+)$/.exec(type);
  if (m) {
    const bits = Number(m[1]);
    if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'bigint') {
      throw new TypeError(`${where}: expected an unsigned integer`);
    }
    if (typeof value === 'string' && !/^\d+$/.test(value)) {
      throw new TypeError(`${where}: expected a decimal integer string`);
    }
    const v = BigInt(value);
    if (v < 0n || v >= 1n << BigInt(bits)) throw new RangeError(`${where}: out of range for ${type}`);
    return word(v);
  }
  throw new Error(`${where}: unsupported EIP-712 type ${type} (flat structs only)`);
}

/** hashStruct for a flat struct whose fields are all atomic/dynamic (no nested structs). */
export function hashFlatStruct(
  primaryType: string,
  fields: readonly TypedDataField[],
  data: Record<string, unknown>,
): Uint8Array {
  const parts: Uint8Array[] = [keccak_256(utf8(encodeFlatType(primaryType, fields)))];
  for (const f of fields) {
    if (!(f.name in data)) throw new Error(`${primaryType}.${f.name} is missing`);
    parts.push(encodeField(f.type, data[f.name], `${primaryType}.${f.name}`));
  }
  return keccak_256(concat(...parts));
}

/** Every struct type `type` references (transitively), including itself. */
function structDependencies(
  type: string,
  types: Record<string, readonly TypedDataField[]>,
  found: Set<string> = new Set(),
): Set<string> {
  if (found.has(type) || !types[type]) return found;
  found.add(type);
  for (const f of types[type]!) {
    if (/\[\d*\]$/.test(f.type)) throw new Error(`${type}.${f.name}: EIP-712 arrays are not supported`);
    structDependencies(f.type, types, found);
  }
  return found;
}

/**
 * EIP-712 `encodeType`: the primary type, then every referenced struct type
 * sorted by name - `CallForPermit(address to,WithdrawToken cmd,...)WithdrawToken(...)`.
 * For a flat struct this is exactly `encodeFlatType`.
 */
export function encodeType(primaryType: string, types: Record<string, readonly TypedDataField[]>): string {
  const deps = [...structDependencies(primaryType, types)].filter((t) => t !== primaryType).sort();
  return [primaryType, ...deps].map((t) => encodeFlatType(t, types[t]!)).join('');
}

/** EIP-712 `hashStruct`, nested structs included (arrays are refused). */
export function hashStruct(
  primaryType: string,
  types: Record<string, readonly TypedDataField[]>,
  data: Record<string, unknown>,
): Uint8Array {
  const fields = types[primaryType];
  if (!fields) throw new Error(`typed data has no type ${primaryType}`);
  const parts: Uint8Array[] = [keccak_256(utf8(encodeType(primaryType, types)))];
  for (const f of fields) {
    if (!(f.name in data)) throw new Error(`${primaryType}.${f.name} is missing`);
    const v = data[f.name];
    if (f.type !== primaryType && f.type in types) {
      if (typeof v !== 'object' || v === null) throw new TypeError(`${primaryType}.${f.name}: expected a ${f.type} struct`);
      parts.push(hashStruct(f.type, types, v as Record<string, unknown>));
    } else {
      parts.push(encodeField(f.type, v, `${primaryType}.${f.name}`));
    }
  }
  return keccak_256(concat(...parts));
}

/**
 * The digest a spec-compliant wallet computes for `td` under eth_signTypedData_v4.
 * Tests pin this against the Go SDK's digests (flat structs) and against viem
 * and the ValueChain permit contract's own `hashCallForPermit` (nested), which
 * proves the typed-data OBJECTS this package hands to wallets hash to what the
 * verifier checks.
 */
export function hashTypedData(td: TypedData): Uint8Array {
  const domainFields = td.types['EIP712Domain'] ?? EIP712_DOMAIN_FIELDS;
  const { EIP712Domain: _domain, ...types } = td.types;
  return keccak_256(
    concat(
      new Uint8Array([0x19, 0x01]),
      hashFlatStruct('EIP712Domain', domainFields, td.domain as unknown as Record<string, unknown>),
      hashStruct(td.primaryType, types, td.message as Record<string, unknown>),
    ),
  );
}

/**
 * The `eth_signTypedData_v4` object for an ExchangeAction - what a MASTER WALLET
 * signs to revoke an API key (0x01, engine domain) or to trade directly.
 *
 * Wallet note: MetaMask refuses typed data whose domain chainId differs from the
 * wallet's active chain, and this domain carries the SoDEX chain id (286623), so
 * the wallet must be on ValueChain for this prompt. Unverified with every wallet.
 */
export function exchangeActionTypedData(
  domainName: string,
  chainId: number,
  payloadHash: Uint8Array,
  nonce: bigint,
): TypedData<'ExchangeAction'> {
  return {
    domain: { name: domainName, version: '1', chainId, verifyingContract: ZERO_ADDRESS },
    types: {
      EIP712Domain: EIP712_DOMAIN_FIELDS,
      ExchangeAction: [
        { name: 'payloadHash', type: 'bytes32' },
        { name: 'nonce', type: 'uint64' },
      ],
    },
    primaryType: 'ExchangeAction',
    message: { payloadHash: bytesToHex(payloadHash), nonce: nonce.toString() },
  };
}

// ---------------------------------------------------------------------------
// Signing
// ---------------------------------------------------------------------------

/**
 * Sign a 32-byte digest and return the 66-byte SoDEX wire signature:
 *   [signatureType] [r:32] [s:32] [v:1]
 * where v is normalised to 0/1 (go-ethereum's crypto.Sign convention).
 */
export function signDigest(digest: Uint8Array, privateKey: Uint8Array, sigType: number): Uint8Array {
  const sig = secp256k1.sign(digest, privateKey, { lowS: true, prehash: false });
  const compact = sig.toCompactRawBytes(); // r||s, 64 bytes
  return concat(new Uint8Array([sigType]), compact, new Uint8Array([sig.recovery & 1]));
}

/** Sign a trading action. Returns the `X-API-Sign` header value. */
export function signExchangeAction(
  domainName: string,
  chainId: number,
  actionType: string,
  params: unknown,
  nonce: bigint,
  privateKey: Uint8Array,
): Hex {
  const digest = exchangeActionDigest(domainName, chainId, actionType, params, nonce);
  return bytesToHex(signDigest(digest, privateKey, SignatureType.EIP712));
}

/** Recover the signer address from a 32-byte digest + 65-byte (r,s,v) signature. */
export function recoverAddress(digest: Uint8Array, rsv: Uint8Array): Hex {
  if (rsv.length !== 65) throw new Error('expected 65-byte signature');
  const v = rsv[64]!;
  const rec = v >= 27 ? v - 27 : v;
  if (rec !== 0 && rec !== 1) throw new Error(`unexpected recovery id ${v}`);
  const sig = secp256k1.Signature.fromCompact(rsv.slice(0, 64)).addRecoveryBit(rec);
  const pub = sig.recoverPublicKey(digest).toRawBytes(false); // uncompressed, 0x04||X||Y
  return bytesToHex(keccak_256(pub.slice(1)).slice(12));
}

/** Recover the signer of a 66-byte SoDEX WIRE signature ([type][r][s][v]). */
export function recoverWireSigner(digest: Uint8Array, wire: string, expectType?: number): Hex {
  const raw = hexToBytes(wire);
  if (raw.length !== 66) throw new Error(`expected a 66-byte wire signature, got ${raw.length}`);
  if (expectType !== undefined && raw[0] !== expectType) {
    throw new Error(`wire signature type ${raw[0]} != expected ${expectType}`);
  }
  return recoverAddress(digest, raw.slice(1));
}

export const privateKeyToAddress = (privateKey: Uint8Array): Hex =>
  bytesToHex(keccak_256(secp256k1.getPublicKey(privateKey, false).slice(1)).slice(12));
